# =====================================================================
#  construction.map - phishing phrases for construction companies,
#  contractors, engineering, architecture and building suppliers
#  Part of: phywall by Develust Technology
#
#  Format : one regex per line, /pattern/flags (i = case-insensitive,
#           u = UTF-8). No trailing spaces.
#  Note   : PHISH_TEXT scores 0 alone; it only adds points together
#           with a phishing link (PHISH_URL / PHISHING).
#
#  Themes : fake tenders / RFQs / invitations to bid with documents
#           behind a link, drawings / BOQ / specifications to
#           download, subcontractor and supplier bank changes,
#           retention and progress payment lures, fake permits and
#           site inspection notices, bid portal and procurement
#           account lures, fake performance bond / guarantee requests
#
#  Avoided: normal project mails ("drawings attached", "site meeting
#           at 10", "updated schedule"), because builders send and
#           receive them every day.
# =====================================================================

# ===== English =====
# Tenders / RFQs
/(invitation\s+to\s+(bid|tender)|request\s+for\s+(quotation|proposal|tender)|rfq|rfp|itb)[^.]{0,60}(view|download|access|open)\s+(the\s+)?(tender|bid|project)?\s*(documents?|package|files?|specifications?)\s+(here|below|via\s+(the\s+)?link|on\s+(our|the)\s+portal)/i
/(you\s+have\s+been|your\s+company\s+has\s+been)\s+(shortlisted|selected|invited|pre-?qualified)\s+(to|for)\s+(bid|tender|submit\s+a\s+(bid|quotation|proposal))/i
/(tender|bid)\s+(documents?|package)\s+(are|is)\s+(available|ready)(\s+for\s+download)?[^.]{0,30}(log\s*in|sign\s*in|register|portal|link)/i
/(submit|upload)\s+your\s+(bid|tender|quotation|proposal)\s+(before|by|via)[^.]{0,40}(portal|link|secure\s+(platform|site))/i
/(e-?procurement|bid\s+submission|bidding|tender|supplier\s+registration)\s+(portal\s+)?(account|profile|registration)\s+(will\s+be\s+|has\s+been\s+)?(suspended|expired|locked|deactivated)/i
# Drawings / BOQ
/(view|download|review)\s+(the\s+)?(project\s+)?(drawings|blueprints|plans|boq|bill\s+of\s+quantities|specifications|cad\s+files)\s+(via|through|on|using)\s+(the\s+)?(secure\s+)?(link|portal|sharepoint|dropbox|wetransfer|onedrive)/i
/(revised|updated|final)\s+(drawings|boq|bill\s+of\s+quantities|specifications)\s+(have\s+been\s+|has\s+been\s+)?(shared|uploaded)[^.]{0,30}(sign\s*in|log\s*in|verify|password)/i
# Bank changes / payments
/(subcontractor|supplier|vendor|contractor)[^.]{0,40}(changed|new|updated)\s+(bank|banking|account|remittance)\s+(details|information|instructions)/i
/(progress|interim|retention|final)\s+payment\s+(certificate|application|release)[^.]{0,40}(view|download|approve|confirm|sign)\b[^.]{0,12}(here|online|via|below)/i
/(retention|retainage)\s+(money|payment|release)\s+(is\s+)?(ready|approved|pending)[^.]{0,30}(verify|confirm|update)\s+(your\s+)?(bank|account|details)/i
/(invoice|payment)\s+for\s+(the\s+)?(materials?|concrete|steel|rebar|cement|equipment\s+rental|scaffolding)[^.]{0,30}(overdue|outstanding|new\s+account)/i
# Permits / inspections
/(building|construction|site|work)\s+permit\s+(has\s+been\s+|is\s+|was\s+)?(suspended|revoked|rejected|expired|on\s+hold|under\s+review)/i
/(site|safety|building|fire)\s+inspection\s+(report|notice|findings|violation)[^.]{0,30}(view|download|respond|pay)\s+(here|online|via|within)/i
/(stop[-\s]work|work\s+stoppage)\s+order\s+(has\s+been\s+)?(issued|served)/i
# Bonds / guarantees
/(performance|bid|advance\s+payment)\s+(bond|guarantee)\s+(is\s+)?(required|pending|expired)[^.]{0,30}(submit|upload|confirm|pay)/i
/(contract\s+award|letter\s+of\s+award|notice\s+of\s+award|letter\s+of\s+intent)[^.]{0,40}(view|download|sign|accept)\s+(here|online|via|below)/i

