/(invitaci[óo]n\s+a\s+(licitar|ofertar)|solicitud\s+de\s+(cotizaci[óo]n|oferta))[^.]{0,50}(descargue|vea|acceda)\s+(los\s+)?(pliegos|documentos)/iu
/(su\s+empresa\s+ha\s+sido)\s+(preseleccionada|invitada)\s+(a|para)\s+(licitar|presentar\s+oferta)/iu
/(subcontratista|proveedor)[^.]{0,30}(nuevos?|cambio\s+de)\s+(datos\s+bancarios|cuenta\s+bancaria)/iu
/(licencia\s+de\s+obra|permiso\s+de\s+construcci[óo]n)\s+(ha\s+sido\s+)?(suspendid[ao]|revocad[ao]|denegad[ao])/iu

